import sys

def solve():
    input = sys.stdin.read
    data = input().split()

    if not data:
        return

    n = int(data[0])
    a = []
    for i in range(n):
        a.append(int(data[1 + i]))

    seen = {0}
    current_sum = 0
    ans = 0

    for x in a:
        current_sum += x
        if current_sum in seen:
            ans += 1
            seen = {0}
            current_sum = 0
        else:
            seen.add(current_sum)

    print(ans)

if __name__ == "__main__":
    solve()
